const $=s=>document.querySelector(s), app=$('#app');
const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}).format(n||0);
const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a, pick=a=>a[Math.floor(Math.random()*a.length)], clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const SAVE_KEY='aflCareerSave';
const GAME_VERSION='0.9.2';
const PREF_KEY='aflCareerPrefs';
let prefs=JSON.parse(localStorage.getItem(PREF_KEY)||'null')||{sound:true,music:true,vibration:true};
function savePrefs(){localStorage.setItem(PREF_KEY,JSON.stringify(prefs))}
function tone(freq=440,duration=.08,type='sine',volume=.05){if(!prefs.sound)return;try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.value=volume;o.connect(g);g.connect(ctx.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.stop(ctx.currentTime+duration)}catch(e){}}
function buzz(pattern){if(prefs.vibration&&navigator.vibrate)navigator.vibrate(pattern)}
let crowdTimer=null;
function crowdTone(level=.5){if(!prefs.music)return;clearTimeout(crowdTimer);let pulses=Math.max(2,Math.round(3+level*5)),i=0;function pulse(){if(i++>=pulses)return;tone(75+rnd(-12,18),.16,'triangle',.012+level*.012);crowdTimer=setTimeout(pulse,110)}pulse()}
function siren(long=false){if(!prefs.sound)return;[0,180,360].forEach((d,i)=>setTimeout(()=>tone(210-i*8,long?.42:.24,'sawtooth',.045),d))}
function broadcastLine(){let margin=score(match.us)-score(match.them),leader=margin===0?'Nothing separates them':`${team(margin>0?state.club:match.oppId).name} lead by ${Math.abs(margin)}`;let star=topPossessions(1)[0];return pick([`${leader} as the clock keeps moving.`,`${star.name} has been prominent with ${star.disp} disposals.`,`The pressure around the contest is lifting.`,`${team(state.club).name} are trying to use ${match.ourPlan.toLowerCase()}.`,`${team(match.oppId).name} have shifted into ${match.theirPlan.toLowerCase()}.`,match.q===4&&match.time<=5?'Every possession matters now.':'This game is being played at a fierce tempo.'])}
function goalCelebration(playerName,clubId){crowdTone(clubId===state.club?1:.7);let el=document.createElement('div');el.className='goal-celebration';el.innerHTML=`<div class="goal-flash">GOAL</div><div class="goal-player">${playerName}</div><div class="goal-six">SIX POINTS</div>`;document.body.appendChild(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),250)},1250)}
function instantReplay(title,detail){let el=document.createElement('div');el.className='replay-overlay';el.innerHTML=`<div class="replay-tag">INSTANT REPLAY</div><div class="replay-ball">🏉</div><h2>${title}</h2><p>${detail}</p>`;document.body.appendChild(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),250)},1450)}

let state=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');
let creator={name:'',position:'MID',height:188,weight:86,skin:'#b77851',hair:'#24160e',hairStyle:'Classic',number:7,foot:'Right',points:32,attrs:{}};
let match=null,slider=null;
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state))}
function restartCareer(){localStorage.removeItem(SAVE_KEY);state=null;creator={name:'',position:'MID',height:188,weight:86,skin:'#b77851',hair:'#24160e',hairStyle:'Classic',number:7,foot:'Right',points:32,attrs:{}};character()}
async function resetAllData(){localStorage.clear();sessionStorage.clear();if('caches' in window){const keys=await caches.keys();await Promise.all(keys.map(k=>caches.delete(k)))}if('serviceWorker' in navigator){const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()))}location.reload()}
function reset(){restartCareer()}
function team(id){return TEAMS.find(t=>t.id===id)}
function roster(id){return REAL_PLAYERS.filter(p=>p.club===id)}
function playerByName(n){return REAL_PLAYERS.find(p=>p.name===n)}
function shell(body){app.innerHTML=`<main class="shell"><div class="brand"><div class="brandmark"><span>AFC</span></div><div><div class="eyebrow">Unofficial Australian football career simulator</div><h1>AFL Career</h1><div class="version">Version ${GAME_VERSION}</div></div></div>${body}</main>`}
function ensureState(){if(!state)return; if(state.version===GAME_VERSION)return;
 state.version=GAME_VERSION; state.phase=state.phase||'regular'; state.round=state.round||1; state.season=state.season||1;
 state.player.seasonGames=state.player.seasonGames||state.player.games||0; state.player.seasonGoals=state.player.seasonGoals||state.player.goals||0; state.player.seasonVotes=state.player.seasonVotes||state.player.votes||0;
 state.player.injury=null; state.player.suspension=0; state.player.form=state.player.form||70; state.player.fitness=state.player.fitness||100;
 state.schedule=makeFixture(state.season); state.currentFixture=0; state.stats=state.stats||{}; state.awards=state.awards||[]; state.records=state.records||{}; state.news=state.news||[];
 state.ladder=blankLadder(); state.brownlow=state.brownlow||{}; state.goals=state.goals||{}; state.seasonStats=state.seasonStats||{}; save();}
function home(){ensureState();let career=state?`<section class="career-preview"><div><small>Current Career</small><strong>${state.player.name}</strong><span>${team(state.club).name} · Season ${state.season} · Round ${Math.min(state.round,23)}</span></div><div class="career-badge">${state.player.seasonVotes}<small>votes</small></div></section>`:'';shell(`<section class="card hero mainmenu"><div class="award football-spin">🏉</div><h2>Australian Football Career</h2><p>Build a 25-season football legacy and chase premierships, Brownlow Medals and career records.</p>${career}${state?`<button onclick="hub()">▶ Resume Career</button><button class="secondary" onclick="newCareerPrompt()">⭐ Start New Career</button>`:`<button onclick="character()">⭐ Start New Career</button>`}<button class="secondary" onclick="about()">Game Guide</button><button class="ghost" onclick="settings()">⚙ Settings</button><div class="menu-version">Version ${GAME_VERSION}</div></section><p class="notice">Real club and player names are included in this private, unofficial fan-made simulator.</p>`)}
function newCareerPrompt(){if(confirm('Start a new career? Your current career will be permanently overwritten.'))restartCareer()}
function restartCareerPrompt(){if(confirm('Restart your career? This will permanently delete the current career but keep the game installed.'))restartCareer()}
function settings(){shell(`<section class="card"><div class="eyebrow">Game settings</div><h2>Settings</h2><div class="toggle-row"><span>Sound effects</span><button class="toggle ${prefs.sound?'on':''}" onclick="prefs.sound=!prefs.sound;savePrefs();settings()">${prefs.sound?'On':'Off'}</button></div><div class="toggle-row"><span>Stadium atmosphere</span><button class="toggle ${prefs.music?'on':''}" onclick="prefs.music=!prefs.music;savePrefs();settings()">${prefs.music?'On':'Off'}</button></div><div class="toggle-row"><span>Vibration</span><button class="toggle ${prefs.vibration?'on':''}" onclick="prefs.vibration=!prefs.vibration;savePrefs();settings()">${prefs.vibration?'On':'Off'}</button></div><div class="listitem"><span>Installed version</span><b>${GAME_VERSION}</b></div><button class="secondary" onclick="home()">Return to Main Menu</button></section><section class="card danger-card"><h3>Restart Career</h3><p>Deletes the current career and returns to character creation.</p><button class="danger" onclick="restartCareerPrompt()" ${state?'':'disabled'}>Restart Career</button></section><section class="card danger-card"><h3>Reset All Game Data</h3><p>Permanently clears saves, preferences, cached files and offline installation data.</p><button class="danger" onclick="if(confirm('Reset all AFL Career game data? This cannot be undone.'))resetAllData()">Reset All Game Data</button></section>`)}
function about(){shell(`<section class="card"><h2>What is new in v0.9.2</h2><p>Structural realism update: proper AFL top-eight finals, valid 23-player selection, live background statistics, position-aware best-on-ground presentation and persistent season records for every player.</p><button onclick="home()">Back</button></section>`)}
function baseAttrs(pos){let o={};POSITIONS[pos].skills.forEach(s=>o[s]=62);return o}
function character(){creator.attrs=baseAttrs(creator.position);creator.points=32;renderCreator()}
function renderCreator(){shell(`<section class="card"><div class="eyebrow">Step 1 of 2</div><h2>Create your player</h2><div class="avatar" style="--skin:${creator.skin};--hair:${creator.hair}"><div class="head"></div><div class="hair"></div><div class="body"></div><div class="shorts"></div><div class="num">${creator.number}</div></div><div class="field"><label>Player name</label><input id="pname" value="${creator.name}" placeholder="Enter your name"></div><div class="grid3">${Object.entries(POSITIONS).map(([k,v])=>`<div class="option ${creator.position===k?'active':''}" onclick="setPos('${k}')"><b>${v.name}</b></div>`).join('')}</div><div class="grid2"><div class="field"><label>Height: ${creator.height} cm</label><input type="range" min="175" max="205" value="${creator.height}" oninput="creator.height=+this.value;renderCreator()"></div><div class="field"><label>Weight: ${creator.weight} kg</label><input type="range" min="70" max="115" value="${creator.weight}" oninput="creator.weight=+this.value;renderCreator()"></div><div class="field"><label>Skin tone</label><select onchange="creator.skin=this.value;renderCreator()"><option value="#f0c7a5">Light</option><option value="#d49a6a">Medium</option><option value="#b77851">Tan</option><option value="#815235">Deep</option><option value="#4f2f20">Dark</option></select></div><div class="field"><label>Hair colour</label><select onchange="creator.hair=this.value;renderCreator()"><option value="#24160e">Dark brown</option><option value="#090909">Black</option><option value="#b87932">Blond</option><option value="#8e3b22">Auburn</option></select></div><div class="field"><label>Guernsey number</label><input type="number" min="1" max="99" value="${creator.number}" onchange="creator.number=clamp(+this.value,1,99)"></div><div class="field"><label>Preferred foot</label><select onchange="creator.foot=this.value"><option>Right</option><option>Left</option></select></div></div><button onclick="toAttributes()">Allocate Attributes</button><button class="ghost" onclick="home()">Cancel</button></section>`)}
function setPos(p){creator.name=$('#pname')?.value||creator.name;creator.position=p;creator.attrs=baseAttrs(p);creator.points=32;renderCreator()}
function toAttributes(){creator.name=$('#pname').value.trim()||'Rookie Star';attributeScreen()}
function overall(){let v=Object.values(creator.attrs);return Math.round(v.reduce((a,b)=>a+b,0)/v.length)}
function attributeScreen(){shell(`<section class="card"><div class="eyebrow">Step 2 of 2</div><div class="topbar"><h2>Build your game</h2><span class="pill">${creator.points} points</span></div><p>Starting overall: <b>${overall()}</b>. Creation maximum is 82.</p>${Object.entries(creator.attrs).map(([k,v])=>`<div class="statrow"><span>${k}</span><div class="bar"><div class="fill" style="width:${v}%"></div></div><b>${v}</b></div><div class="grid2"><button class="secondary" onclick="changeAttr('${k}',-1)">−</button><button class="secondary" onclick="changeAttr('${k}',1)">+</button></div>`).join('')}<button class="gold" onclick="draft()" ${creator.points>0?'disabled':''}>Enter the Draft</button><button class="ghost" onclick="renderCreator()">Back</button></section>`)}
function changeAttr(k,d){if(d>0&&(creator.points<=0||creator.attrs[k]>=82))return;if(d<0&&creator.attrs[k]<=55)return;creator.attrs[k]+=d;creator.points-=d;attributeScreen()}
function blankLadder(){return TEAMS.map(t=>({id:t.id,p:0,w:0,l:0,d:0,pf:0,pa:0,pts:0}))}
function makeFixture(seed){let ids=TEAMS.map(t=>t.id), games=[]; for(let r=1;r<=23;r++){let rot=(r*5+seed*3)%ids.length; let order=ids.slice(rot).concat(ids.slice(0,rot)); if(r%2)order.reverse(); let pair=[]; for(let i=0;i<9;i++)pair.push({home:order[i],away:order[17-i]}); games.push(pair)} return games}
function draft(){let t=pick(TEAMS);state={version:GAME_VERSION,phase:'regular',season:1,round:1,currentFixture:0,player:{...creator,age:18,overall:overall(),club:t.id,games:0,goals:0,votes:0,seasonGames:0,seasonGoals:0,seasonVotes:0,premierships:0,brownlows:0,colemans:0,careerEarnings:0,cash:0,fitness:100,form:70,injury:null,suspension:0},club:t.id,contract:{years:2,salary:210000,matchPayment:5500},ladder:blankLadder(),schedule:makeFixture(1),history:[],assets:[],sponsors:[],brownlow:{},goals:{},awards:[],records:{},news:[`${creator.name} selected by ${t.name} with Pick No. 1.`],seasonStats:{},seasonSummary:null};save();shell(`<section class="card hero" style="border-color:${t.primary}"><div class="eyebrow">Pick No. 1</div><h2>${t.name}</h2><div class="avatar" style="--skin:${creator.skin};--hair:${creator.hair};--team:${t.primary}"><div class="head"></div><div class="hair"></div><div class="body"></div><div class="shorts"></div><div class="num">${creator.number}</div></div><p>With the first selection, <b>${t.name}</b> select <b>${creator.name}</b>, ${POSITIONS[creator.position].name.toLowerCase()}.</p><div class="card"><b>Two-year contract</b><br>${money(state.contract.salary)} per season · ${money(state.contract.matchPayment)} per senior match</div><button onclick="hub()">Begin Career</button></section>`)}
function nav(){return `<div class="nav"><button onclick="home()">Menu</button><button onclick="hub()">Career</button><button onclick="league()">League</button><button onclick="finance()">Money</button><button onclick="profile()">Player</button></div>`}
function findUserFixture(){let round=state.schedule[state.round-1]||[];return round.find(g=>g.home===state.club||g.away===state.club)}
function ladderSorted(){return [...state.ladder].sort((a,b)=>b.pts-a.pts||percentage(b)-percentage(a)||b.pf-a.pf)}
function percentage(x){return x.pa?100*x.pf/x.pa:0}
function availability(){if(state.player.injury)return `Injured · ${state.player.injury.weeks} week${state.player.injury.weeks===1?'':'s'}`;if(state.player.suspension>0)return `Suspended · ${state.player.suspension} match${state.player.suspension===1?'':'es'}`;return 'Available'}
function hub(){ensureState();let t=team(state.club); if(state.phase==='seasonEnd')return seasonReview(); if(state.phase==='finals')return finalsHub(); let fx=findUserFixture(),opp=team(fx.home===state.club?fx.away:fx.home),rank=ladderSorted().findIndex(x=>x.id===state.club)+1;shell(`<section class="card" style="border-top:5px solid ${t.primary}"><div class="topbar"><div><div class="eyebrow">Season ${state.season} · Round ${state.round}</div><h2>${t.name}</h2></div><span class="pill">OVR ${state.player.overall}</span></div><div class="grid2"><div><small class="muted">Next opponent</small><h3>${opp.name}</h3></div><div><small class="muted">Ladder</small><h3>${rank}${['st','nd','rd'][rank-1]||'th'}</h3></div></div><div class="listitem"><span>Status</span><b>${availability()}</b></div><div class="listitem"><span>Fitness</span><b>${state.player.fitness}%</b></div><button onclick="preview('${opp.id}')">${availability()==='Available'?'Play':'Simulate'} Round ${state.round}</button></section><section class="grid2"><div class="card"><div class="eyebrow">Season games</div><h2>${state.player.seasonGames}</h2><span class="muted">Career ${state.player.games}</span></div><div class="card"><div class="eyebrow">Brownlow estimate</div><h2>${state.player.seasonVotes}</h2><span class="muted">votes</span></div></section><section class="card"><h3>Season snapshot</h3><div class="listitem"><span>Goals</span><b>${state.player.seasonGoals}</b></div><div class="listitem"><span>Form</span><b>${state.player.form}</b></div><div class="listitem"><span>Current cash</span><b>${money(state.player.cash)}</b></div><div class="listitem"><span>Contract remaining</span><b>${state.contract.years} years</b></div></section>${state.news.length?`<section class="card"><h3>Latest news</h3>${state.news.slice(-4).reverse().map(n=>`<p>${n}</p>`).join('')}</section>`:''}${nav()}`)}
function preview(oppId){let a=team(state.club),b=team(oppId),unavailable=availability()!=='Available';shell(`<section class="card hero"><div class="eyebrow">Season ${state.season} · Round ${state.round}</div><h2>${a.name}<br><span class="muted">vs</span><br>${b.name}</h2><p>${unavailable?`You are ${availability().toLowerCase()}. The match will be simulated.`:`Selected at ${POSITIONS[state.player.position].name}. Decisions appear whenever play reaches your player.`}</p><button onclick="${unavailable?`simulateUserAbsent('${oppId}')`:`startMatch('${oppId}')`}">${unavailable?'Simulate Match':'Centre Bounce'}</button><button class="ghost" onclick="hub()">Back</button></section>`)}
function eliteBoost(name){return ['Marcus Bontempelli','Nick Daicos','Max Gawn','Isaac Heeney','Patrick Cripps','Zak Butters','Caleb Serong','Noah Anderson','Tom Green','Errol Gulden','Jordan Dawson','Bailey Smith','Nasiah Wanganeen-Milera'].includes(name)?rnd(2,6):0}
function seedMatchPlayers(clubId){let list=roster(clubId).slice().sort((a,b)=>b.ovr-a.ovr).slice(0,22);return list.map(p=>{let archetype=p.pos==='RUC'?'RUC':p.pos==='FWD'?'FWD':p.pos==='DEF'?'DEF':'MID',base=p.d||({MID:23,FWD:13,DEF:19,RUC:16}[archetype]||18),target=clamp(Math.round(base*(.90+Math.random()*.24)+eliteBoost(p.name)),archetype==='FWD'?7:10,archetype==='MID'?43:36);return {name:p.name,club:clubId,pos:archetype,ovr:p.ovr,avg:p.avg||0,targetDisp:target,disp:0,k:0,h:0,m:0,t:0,g:0,b:0,clr:0,int:0,ho:0,impact:0}})}
function selectedSide(clubId,includeCreated=false){let list=seedMatchPlayers(clubId);if(!includeCreated)return list.slice(0,23);let pos=state.player.position,idx=-1,worst=999;list.forEach((p,i)=>{if(p.pos===pos&&p.ovr<worst){worst=p.ovr;idx=i}});if(idx<0)idx=list.reduce((w,p,i,a)=>p.ovr<a[w].ovr?i:w,0);list.splice(idx,1);list.push({name:state.player.name,club:state.club,pos,ovr:state.player.overall,targetDisp:clamp(Math.round(15+(state.player.overall-65)*.45+rnd(-3,4)),12,32),disp:0,k:0,h:0,m:0,t:0,g:0,b:0,clr:0,int:0,ho:0,impact:0,created:true});return list.slice(0,23)}
function startMatch(oppId){let ours=selectedSide(state.club,true),theirs=selectedSide(oppId,false);match={oppId,q:1,time:20,us:{g:0,b:0},them:{g:0,b:0},stats:{disp:0,k:0,h:0,m:0,t:0,g:0,b:0,clr:0,int:0,ho:0,impact:0},players:[...ours,...theirs],log:['The umpire sends the ball into the air.'],awaitingBreak:false,phase:'contest',zone:'CENTRE',hasBall:false,shot:null,momentum:0,ourPlan:'Balanced',theirPlan:'Balanced',tagged:false,lastTacticMinute:20,venue:pick(['MCG','Marvel Stadium','Adelaide Oval','Optus Stadium','SCG','The Gabba']),weather:pick(['Clear · 18°C','Cool · 13°C','Dry · 21°C','Light breeze · 16°C']),attendance:rnd(28600,93800),broadcastNotes:[]};matchIntro()}
function matchIntro(){let a=team(state.club),b=team(match.oppId),spot=pick([`${state.player.name} enters with form rated ${state.player.form}.`,`${a.name} want to establish control around the contest.`,`${b.name} arrive with a plan to pressure the ball carrier.`]);siren();crowdTone(.45);shell(`<section class="broadcast-intro tv-intro" style="--a:${a.primary};--b:${b.primary}"><div class="broadcast-network">FOOTBALL LIVE</div><div class="eyebrow">Season ${state.season} · Round ${state.round}</div><h2>MATCH DAY</h2><div class="versus"><strong>${a.name}</strong><span>VS</span><strong>${b.name}</strong></div><div class="venue-strip"><span>${match.venue}</span><span>${match.weather}</span><span>${match.attendance.toLocaleString('en-AU')} attending</span></div><div class="pre-game-desk"><div class="desk-label">COMMENTARY DESK</div><p>${spot}</p></div><div class="centre-ball">🏉</div><h3>FIRST QUARTER · CENTRE BOUNCE</h3><button onclick="renderMatch();setTimeout(nextEvent,450)">Begin Broadcast</button></section>`)}
function resultBanner(title,detail,type='success',icon='✓'){tone(type==='fail'?160:type==='goal'?620:440,type==='goal'?.22:.09,type==='fail'?'sawtooth':'sine',.06);buzz(type==='goal'?[100,50,180]:type==='fail'?[70,45,70]:[55]);let el=document.createElement('div');el.className=`result-overlay ${type}`;el.innerHTML=`<div class="result-icon">${icon}</div><div class="result-title">${title}</div><div class="result-detail">${detail||''}</div><div class="flying-ball">🏉</div>`;document.body.appendChild(el);setTimeout(()=>el.classList.add('show'),20);setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),250)},850)}
function score(x){return x.g*6+x.b}
function zoneLabel(){return {D50:'Defensive 50',WING:'Wing',CENTRE:'Centre',HF:'Half-forward',F50:'Forward 50'}[match.zone]||'Centre'}
function topPossessions(limit=5){return [...match.players].sort((a,b)=>b.disp-a.disp||b.ovr-a.ovr).slice(0,limit)}
function renderMatch(actions=''){let a=team(state.club),b=team(match.oppId),dots=match.players.slice(0,18).map((p,i)=>`<i class="player-dot ${p.club===state.club?'ours':'theirs'} ${p.created?'controlled':''}" style="--x:${10+(i*37)%80}%;--y:${16+(i*53)%68}%"></i>`).join(''),call=broadcastLine();shell(`<div class="broadcast-bug"><span>FOOTBALL LIVE</span><b>${match.venue}</b></div><div class="scoreboard broadcast-score" style="--home:${a.primary};--away:${b.primary}"><div class="clock"><span class="live-dot"></span> Q${match.q} · ${String(match.time).padStart(2,'0')}:00</div><div class="teamscore"><div class="score-team home"><b>${a.id}</b><div class="bigscore">${score(match.us)}</div><small>${match.us.g}.${match.us.b}</small></div><div class="live-ball">🏉</div><div class="score-team away"><b>${b.id}</b><div class="bigscore">${score(match.them)}</div><small>${match.them.g}.${match.them.b}</small></div></div></div><section class="commentary-ribbon"><span>ON AIR</span><p>${call}</p></section><section class="oval-stage stadium"><div class="crowd crowd-top"></div><div class="crowd crowd-bottom"></div><div class="oval-lines"></div>${dots}<div class="ball-sprite">🏉</div><div class="event-copy"><div class="eyebrow">${zoneLabel()} · ${match.hasBall?'In possession':'Ball in dispute'}</div><h3>${match.log.at(-1)}</h3></div></section><section class="tactics-strip"><div><small>YOUR PLAN</small><b>${match.ourPlan}</b></div><div class="momentum-meter"><span style="width:${50+match.momentum*1.5}%"></span></div><div><small>OPPOSITION</small><b>${match.theirPlan}${match.tagged?' · TAGGING YOU':''}</b></div></section><section class="card action-panel">${actions||'<div class="waiting">Play developing…</div>'}</section><section class="player-stat-cards"><div><b>${match.stats.disp}</b><span>Disposals</span></div><div><b>${match.stats.g}.${match.stats.b}</b><span>Score</span></div><div><b>${match.stats.t}</b><span>Tackles</span></div></section><section class="card ticker-card"><div class="ticker-head">LIVE COMMENTARY</div><div class="ticker">${match.log.slice(-5).reverse().join('<br>')}</div></section>`)}
function weightedTouch(pool){let weighted=[];pool.forEach(p=>{let need=Math.max(1,(p.targetDisp||18)-p.disp),copies=Math.max(1,Math.round(need/3));for(let i=0;i<copies;i++)weighted.push(p)});return pick(weighted)}
