function addSeasonLine(p){if(!state.seasonStats)state.seasonStats={};let x=state.seasonStats[p.name]||(state.seasonStats[p.name]={club:p.club,pos:p.pos,games:0,disp:0,k:0,h:0,m:0,t:0,g:0,b:0,clr:0,int:0,ho:0,votes:0});x.games++;['disp','k','h','m','t','g','b','clr','int','ho'].forEach(k=>x[k]+=(p[k]||0))}
function recordMatchSeasonStats(votes){match.players.forEach(addSeasonLine);Object.entries(votes).forEach(([n,v])=>{if(state.seasonStats[n])state.seasonStats[n].votes+=v})}
function finishMatch(){siren(true);finaliseRealStats();let fx=findUserFixture(),win=score(match.us)>score(match.them),pay=state.contract.matchPayment,voteData=matchVotes(),leaders=voteData.ranked.slice(0,8),votes=voteData.out[state.player.name]||0;recordMatchSeasonStats(voteData.out);state.player.games++;state.player.seasonGames++;state.player.goals+=match.stats.g;state.player.seasonGoals+=match.stats.g;state.goals[state.player.name]=(state.goals[state.player.name]||0)+match.stats.g;state.player.cash+=pay;state.player.careerEarnings+=pay;state.player.fitness=clamp(state.player.fitness-rnd(10,20),20,100);state.player.form=clamp(Math.round(state.player.form*.75+(50+match.stats.impact)*.25),35,95);state.player.votes+=votes;state.player.seasonVotes+=votes;Object.entries(voteData.out).forEach(([name,v])=>state.brownlow[name]=(state.brownlow[name]||0)+v);state.history.push({season:state.season,round:state.round,opponent:match.oppId,result:win?'W':'L',score:`${score(match.us)}-${score(match.them)}`,stats:match.stats,votes});simulateOtherGames(fx,match.us,match.them);maybeInjury();let world=postMatchWorld(win,votes,leaders);state.news.push(world.headline);if(Math.random()<.28)state.news.push(pick([`${state.player.name} is attracting sponsor interest after a strong run of form.`,`Coach challenges ${state.player.name} to improve disposal efficiency.`,`Supporters are calling for ${state.player.name} to take on more responsibility.`,`A rival club is reportedly monitoring ${state.player.name}'s contract situation.`]));progressRound();save();shell(`<section class="final-screen ${win?'win':'loss'}" style="--home:${team(state.club).primary};--away:${team(match.oppId).primary}"><div class="award">${win?'🏆':'🏉'}</div><div class="eyebrow">FINAL SCORE</div><h2>${win?'VICTORY':'DEFEAT'}</h2><div class="break-score"><div><strong>${team(state.club).name}</strong><b>${match.us.g}.${match.us.b} (${score(match.us)})</b></div><div><strong>${team(match.oppId).name}</strong><b>${match.them.g}.${match.them.b} (${score(match.them)})</b></div></div></section><section class="player-stat-cards final-stats"><div><b>${match.stats.disp}</b><span>Disposals</span></div><div><b>${match.stats.g}.${match.stats.b}</b><span>Goals</span></div><div><b>${votes}</b><span>Votes</span></div></section><section class="potm-screen"><div class="broadcast-network">PLAYER OF THE MATCH</div><div class="potm-medal">★</div><h2>${leaders[0].name}</h2><p>${team(leaders[0].club).name} · ${statLine(leaders[0])}</p></section><section class="card"><h3>⭐ Best on Ground</h3>${leaders.map((p,i)=>`<div class="performer ${i===0?'bog':''}"><span><b>${i+1}. ${p.name}</b><small>${team(p.club).name} · ${statLine(p)}${p.created?' · Your player':''}</small></span><strong>${p.disp}</strong></div>`).join('')}</section><section class="card reaction-card"><div class="eyebrow">Coach's comments</div><h3>${world.coach}</h3><p>${world.brownlow}</p></section><section class="card media-card"><div class="eyebrow">Football Tonight</div><h3>${world.headline}</h3><p>${world.mate}</p></section><section class="card"><h3>Fan reaction</h3>${world.fans.map(x=>`<p class="fan-quote">${x}</p>`).join('')}<div class="listitem"><span>Match payment</span><b>${money(pay)}</b></div><button onclick="hub()">Continue Career</button></section>`);tone(win?620:180,.28,win?'sine':'sawtooth',.055);buzz(win?[120,70,200]:[120])}
function simulateUserAbsent(oppId){let fx=findUserFixture(),us=simScore(team(state.club).strength),them=simScore(team(oppId).strength);simulateOtherGames(fx,us,them);progressRound();shell(`<section class="card hero"><div class="eyebrow">Full time</div><h2>${score(us)>score(them)?'Club victory':'Club defeat'}</h2><p>${team(state.club).name} ${score(us)} — ${score(them)} ${team(oppId).name}</p><p>You did not play because you were ${availability().toLowerCase()}.</p><button onclick="hub()">Continue</button></section>`)}
function finalsGame(a,b,label){let as=team(a).strength+rnd(-9,9)+(a===state.club?state.player.overall/12:0),bs=team(b).strength+rnd(-9,9)+(b===state.club?state.player.overall/12:0),winner=as===bs?(Math.random()<.5?a:b):(as>bs?a:b);state.finals.results.push({week:state.finals.week,label,a,b,winner});return winner}
function prepareFinals(){let top=ladderSorted().slice(0,8).map(x=>x.id);state.finals={week:1,top,alive:[...top],results:[],champion:null,bracket:{}};state.news.push(`The home-and-away season is complete. ${team(top[0]).name} finished on top.`)}
function finalsFixtures(){let f=state.finals,t=f.top,b=f.bracket;if(f.week===1)return [['Qualifying Final',t[0],t[3]],['Qualifying Final',t[1],t[2]],['Elimination Final',t[4],t[7]],['Elimination Final',t[5],t[6]]];if(f.week===2)return [['Semi Final',b.qf1l,b.ef2w],['Semi Final',b.qf2l,b.ef1w]];if(f.week===3)return [['Preliminary Final',b.qf1w,b.sf2w],['Preliminary Final',b.qf2w,b.sf1w]];if(f.week===4)return [['Grand Final',b.pf1w,b.pf2w]];return []}
function finalsHub(){let f=state.finals;if(f.champion){state.phase='seasonEnd';save();return seasonReview()}let games=finalsFixtures(),inRound=games.some(x=>x[1]===state.club||x[2]===state.club);shell(`<section class="card hero"><div class="eyebrow">Finals · Week ${f.week}</div><h2>${f.week===4?'Grand Final':inRound?'Your premiership campaign continues':'Finals series'}</h2><p>${inRound?'Your club is alive in the premiership race.':'Simulate the current finals week.'}</p><button onclick="playFinalsWeek()">${inRound?'Play Finals Week':'Simulate Finals Week'}</button></section><section class="card"><h3>This week</h3>${games.map(x=>`<div class="listitem"><span>${x[0]}<br><small>${team(x[1]).name} vs ${team(x[2]).name}</small></span></div>`).join('')}</section>${nav()}`)}
function playFinalsWeek(){let f=state.finals,g=finalsFixtures(),w=g.map(x=>finalsGame(x[1],x[2],x[0])),b=f.bracket;if(f.week===1){b.qf1w=w[0];b.qf1l=w[0]===g[0][1]?g[0][2]:g[0][1];b.qf2w=w[1];b.qf2l=w[1]===g[1][1]?g[1][2]:g[1][1];b.ef1w=w[2];b.ef2w=w[3];f.alive=[b.qf1w,b.qf1l,b.qf2w,b.qf2l,b.ef1w,b.ef2w]}else if(f.week===2){b.sf1w=w[0];b.sf2w=w[1];f.alive=[b.qf1w,b.qf2w,b.sf1w,b.sf2w]}else if(f.week===3){b.pf1w=w[0];b.pf2w=w[1];f.alive=[b.pf1w,b.pf2w]}else{f.champion=w[0];f.alive=[w[0]];if(f.champion===state.club){state.player.premierships++;state.player.cash+=100000;state.player.careerEarnings+=100000;state.news.push(`${state.player.name} is a premiership player!`)}state.phase='seasonEnd'}f.week++;save();hub()}
function seasonReview(){if(!state.seasonSummary){let votes=Object.entries(state.brownlow).sort((a,b)=>b[1]-a[1]),goals=Object.entries(state.goals).sort((a,b)=>b[1]-a[1]),brown=votes[0]||['No winner',0],cole=goals[0]||['No winner',0];if(brown[0]===state.player.name){state.player.brownlows++;state.player.cash+=75000;state.player.careerEarnings+=75000}if(cole[0]===state.player.name)state.player.colemans++;state.seasonSummary={premier:state.finals?.champion||ladderSorted()[0].id,brownlow:brown,coleman:cole};save()}let s=state.seasonSummary;shell(`<section class="card hero"><div class="award">🏆</div><div class="eyebrow">Season ${state.season} complete</div><h2>${team(s.premier).name} Premiers</h2><p><b>Brownlow:</b> ${s.brownlow[0]} (${s.brownlow[1]} votes)<br><b>Leading goalkicker:</b> ${s.coleman[0]} (${s.coleman[1]} goals)</p><div class="grid3"><div><b>${state.player.seasonGames}</b><br><small>Games</small></div><div><b>${state.player.seasonGoals}</b><br><small>Goals</small></div><div><b>${state.player.seasonVotes}</b><br><small>Votes</small></div></div><button onclick="newSeason()">Begin Next Season</button></section>${nav()}`)}
function newSeason(){state.player.cash+=state.contract.salary;state.player.careerEarnings+=state.contract.salary;state.contract.years--;if(state.contract.years<=0){state.contract={years:pick([2,3,4,5]),salary:rnd(450,950)*1000,matchPayment:rnd(6,12)*1000};state.news.push(`${state.player.name} signed a new ${state.contract.years}-year contract worth ${money(state.contract.salary)} per season.`)}state.season++;state.round=1;state.phase='regular';state.schedule=makeFixture(state.season);state.ladder=blankLadder();state.brownlow={};state.goals={};state.seasonStats={};state.finals=null;state.seasonSummary=null;state.player.age++;state.player.seasonGames=0;state.player.seasonGoals=0;state.player.seasonVotes=0;state.player.fitness=100;state.player.form=70;if(state.player.age<=25&&Math.random()<.75){let k=pick(Object.keys(state.player.attrs));state.player.attrs[k]=clamp(state.player.attrs[k]+1,40,96);state.player.overall=Math.round(Object.values(state.player.attrs).reduce((a,b)=>a+b,0)/Object.values(state.player.attrs).length)}if(state.season>25){return retirement()}save();hub()}
function retirement(){shell(`<section class="card hero"><div class="award">🏅</div><h2>Career Complete</h2><p>${state.player.name} retires after 25 seasons.</p><div class="listitem"><span>Games</span><b>${state.player.games}</b></div><div class="listitem"><span>Goals</span><b>${state.player.goals}</b></div><div class="listitem"><span>Brownlows</span><b>${state.player.brownlows}</b></div><div class="listitem"><span>Premierships</span><b>${state.player.premierships}</b></div><div class="listitem"><span>Career earnings</span><b>${money(state.player.careerEarnings)}</b></div><button class="ghost" onclick="restartCareerPrompt()">New Career</button></section>`)}
function league(){let standings=ladderSorted(),votes=Object.entries(state.brownlow).sort((a,b)=>b[1]-a[1]).slice(0,10),goals=Object.entries(state.goals).sort((a,b)=>b[1]-a[1]).slice(0,10),stats=Object.entries(state.seasonStats||{}).filter(x=>x[1].games).sort((a,b)=>(b[1].disp/b[1].games)-(a[1].disp/a[1].games)).slice(0,10);shell(`<section class="card"><h2>Ladder</h2>${standings.map((x,i)=>`<div class="listitem"><span>${i+1}. <i class="teamdot" style="background:${team(x.id).primary}"></i>${team(x.id).name}</span><b>${x.pts} · ${percentage(x).toFixed(1)}%</b></div>`).join('')}</section><section class="card"><h2>Disposal Leaders</h2>${stats.length?stats.map((x,i)=>`<div class="listitem"><span>${i+1}. ${x[0]}<br><small>${x[1].games} games</small></span><b>${(x[1].disp/x[1].games).toFixed(1)}</b></div>`).join(''):'<p>No player statistics yet.</p>'}</section><section class="card"><h2>Brownlow Tracker</h2>${votes.length?votes.map((x,i)=>`<div class="listitem"><span>${i+1}. ${x[0]}</span><b>${x[1]}</b></div>`).join(''):'<p>No votes yet.</p>'}</section><section class="card"><h2>Leading Goalkickers</h2>${goals.length?goals.map((x,i)=>`<div class="listitem"><span>${i+1}. ${x[0]}</span><b>${x[1]}</b></div>`).join(''):'<p>No goals yet.</p>'}</section>${nav()}`)}
const SHOP=[['Starter apartment',380000],['Family home',850000],['Beach house',1800000],['Performance SUV',95000],['Luxury coupe',220000],['Home gym',28000],['Recovery suite',65000],['Designer watch',18000]];
function finance(){shell(`<section class="card"><div class="eyebrow">Available cash</div><h2>${money(state.player.cash)}</h2><div class="listitem"><span>Career earnings</span><b>${money(state.player.careerEarnings)}</b></div><div class="listitem"><span>Annual salary</span><b>${money(state.contract.salary)}</b></div><div class="listitem"><span>Match payment</span><b>${money(state.contract.matchPayment)}</b></div></section><section class="card"><h2>Lifestyle</h2>${SHOP.map(([n,p])=>`<div class="listitem"><span>${n}<br><small class="muted">${money(p)}</small></span><button style="width:auto" ${state.player.cash<p||state.assets.includes(n)?'disabled':''} onclick="buy('${n}',${p})">${state.assets.includes(n)?'Owned':'Buy'}</button></div>`).join('')}</section>${nav()}`)}
function buy(n,p){if(state.player.cash>=p){state.player.cash-=p;state.assets.push(n);save();finance()}}
function profile(){let t=team(state.club);shell(`<section class="card"><div class="avatar" style="--skin:${state.player.skin};--hair:${state.player.hair};--team:${t.primary}"><div class="head"></div><div class="hair"></div><div class="body"></div><div class="shorts"></div><div class="num">${state.player.number}</div></div><h2 style="text-align:center">${state.player.name}</h2><p style="text-align:center" class="muted">${POSITIONS[state.player.position].name} · ${state.player.height} cm · ${state.player.weight} kg · Age ${state.player.age}</p>${Object.entries(state.player.attrs).map(([k,v])=>`<div class="statrow"><span>${k}</span><div class="bar"><div class="fill" style="width:${v}%"></div></div><b>${v}</b></div>`).join('')}</section><section class="card"><h3>Career honours</h3><div class="listitem"><span>Premierships</span><b>${state.player.premierships}</b></div><div class="listitem"><span>Brownlows</span><b>${state.player.brownlows}</b></div><div class="listitem"><span>Leading goalkicker awards</span><b>${state.player.colemans}</b></div><button class="ghost" onclick="restartCareerPrompt()">Restart Career</button><button class="secondary" onclick="settings()">Settings</button></section>${nav()}`)}
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');window.addEventListener('pageshow',()=>home());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!match)home()});home();
